  function portraitSource(look){return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(portraitSVG(look));}
  function matchingDetails(input){const p=normalize(input);return `<dl class="matching-facts">${profileFacts(p).map(f=>`<div class="${f.known?'':'not-selected'}"><dt>${f.label}</dt><dd>${escape(f.value)}</dd></div>`).join('')}<div><dt>אירוע</dt><dd>${EVENTS.find(e=>e[0]===p.event)[1]}</dd></div><div><dt>סגנון</dt><dd translate="no">${STYLES.find(s=>s.id===p.style).name}</dd></div></dl>`;}
