  function readFavorites(){try{const data=JSON.parse(localStorage.getItem(storageKey)||'[]');return Array.isArray(data)?data.slice(0,18).filter(x=>x&&typeof x.id==='string'&&VARIANTS.some(v=>v.id===x.kind)).map(x=>({id:x.id.slice(0,90),kind:x.kind,profile:normalize(x.profile),created:Number.isFinite(x.created)&&x.created>=0&&x.created<=8640000000000000?x.created:Date.now()})):[];}catch{return [];}}
  function persist(){try{localStorage.setItem(storageKey,JSON.stringify(favorites));return true;}catch{toast('לא ניתן לשמור בדפדפן הזה כרגע. אפשר להוריד כרטיס המלצה.');return false;}}
